import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"大招","description":"","frontmatter":{"title":"大招","date":"2026-11-24T00:00:00.000Z","seq":28,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"景差","source_book":"楚辞","prev":{"text":"招魂","link":"/blogs/楚辞/招魂.html"},"next":{"text":"惜誓","link":"/blogs/楚辞/惜誓.html"}},"headers":[],"relativePath":"blogs/楚辞/大招.md","filePath":"blogs/楚辞/大招.md"}'),o={name:"blogs/楚辞/大招.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="大招" tabindex="-1">大招 <a class="header-anchor" href="#大招" aria-label="Permalink to &quot;大招&quot;">​</a></h1><p class="poem-meta">先秦 · 景差　·　大招</p><div class="poem"><p class="poem-stanza">青春受谢，白日昭只。</p><p class="poem-stanza">春气奋发，万物遽只。</p><p class="poem-stanza">冥凌浃行，魂无逃只。</p><p class="poem-stanza">魂魄归来！无远遥只。</p><p class="poem-stanza">魂乎归来！无东无西，无南无北只。</p><p class="poem-stanza">东有大海，溺水浟浟只。</p><p class="poem-stanza">螭龙并流，上下悠悠只。</p><p class="poem-stanza">雾雨淫淫，白皓胶只。</p><p class="poem-stanza">魂乎无东！汤谷寂寥只。</p><p class="poem-stanza">魂乎无南！南有炎火千里，蝮蛇蜒只。</p><p class="poem-stanza">山林险隘，虎豹蜿只。</p><p class="poem-stanza">鰅鳙短狐，王虺骞只。</p><p class="poem-stanza">魂乎无南！蜮伤躬只</p><p class="poem-stanza">魂乎无西！西方流沙，漭洋洋只。</p><p class="poem-stanza">豕首纵目，被发鬤只。</p><p class="poem-stanza">长爪踞牙，诶笑狂只。</p><p class="poem-stanza">魂乎无西！多害伤只。</p><p class="poem-stanza">魂乎无北！北有寒山，趠龙赩只。</p><p class="poem-stanza">代水不可涉，深不可测只。</p><p class="poem-stanza">天白颢颢，寒凝凝只。</p><p class="poem-stanza">魂乎无往！盈北极只。</p><p class="poem-stanza">魂魄归来！闲以静只。</p><p class="poem-stanza">自恣荆楚，安以定只。</p><p class="poem-stanza">逞志究欲，心意安只。</p><p class="poem-stanza">穷身永乐，年寿延只。</p><p class="poem-stanza">魂乎归来！乐不可言只。</p><p class="poem-stanza">五谷六仞，设菰梁只。</p><p class="poem-stanza">鼎臑盈望，和致芳只。</p><p class="poem-stanza">内鸧鸽鹄，味豺羹只。</p><p class="poem-stanza">魂乎归来！恣所尝只。</p><p class="poem-stanza">鲜蠵甘鸡，和楚酪只。</p><p class="poem-stanza">醢豚苦狗，脍苴蒪只。</p><p class="poem-stanza">吴酸蒿蒌，不沾薄只。</p><p class="poem-stanza">魂兮归来！恣所择只。</p><p class="poem-stanza">炙鸹烝凫，煔鹑敶只。</p><p class="poem-stanza">煎鰿膗雀，遽爽存只。</p><p class="poem-stanza">魂乎归来！丽以先只。</p><p class="poem-stanza">四酎并孰，不涩嗌只。</p><p class="poem-stanza">清馨冻饮，不歠役只。</p><p class="poem-stanza">吴醴白蘖，和楚沥只。</p><p class="poem-stanza">魂乎归来！不遽惕只。</p><p class="poem-stanza">代秦郑卫，鸣竽张只。</p><p class="poem-stanza">伏戏《驾辩》，楚《劳商》只。</p><p class="poem-stanza">讴和《扬阿》，赵萧倡只。</p><p class="poem-stanza">魂乎归来！定空桑只。</p><p class="poem-stanza">二八接舞，投诗赋只。</p><p class="poem-stanza">叩钟调磬，娱人乱只。</p><p class="poem-stanza">四上竞气，极声变只。</p><p class="poem-stanza">魂乎归来！听歌譔只。</p><p class="poem-stanza">朱唇皓齿，嫭以姱只。</p><p class="poem-stanza">比德好闲，习以都只。</p><p class="poem-stanza">丰肉微骨，调以娱只。</p><p class="poem-stanza">魂乎归来！安以舒只。</p><p class="poem-stanza">嫮目宜笑，娥眉曼只。</p><p class="poem-stanza">容则秀雅，稚朱颜只。</p><p class="poem-stanza">魂乎归来！静以安只。</p><p class="poem-stanza">姱修滂浩，丽以佳只。</p><p class="poem-stanza">曾颊倚耳，曲眉规只。</p><p class="poem-stanza">滂心绰态，姣丽施只。</p><p class="poem-stanza">小腰秀颈，若鲜卑只。</p><p class="poem-stanza">魂乎归来！思怨移只。</p><p class="poem-stanza">易中利心，以动作只。</p><p class="poem-stanza">粉白黛黑，施芳泽只。</p><p class="poem-stanza">长袂拂面，善留客只。</p><p class="poem-stanza">魂乎归来！以娱昔只。</p><p class="poem-stanza">青色直眉，美目媔只。</p><p class="poem-stanza">靥辅奇牙，宜笑嘕只。</p><p class="poem-stanza">丰肉微骨，体便娟只。</p><p class="poem-stanza">魂乎归来！恣所便只。</p><p class="poem-stanza">夏屋广大，沙堂秀只。</p><p class="poem-stanza">南房小坛，观绝霤只。</p><p class="poem-stanza">曲屋步壛，宜扰畜只。</p><p class="poem-stanza">腾驾步游，猎春囿只。</p><p class="poem-stanza">琼轂错衡，英华假只。</p><p class="poem-stanza">茝兰桂树，郁弥路只。</p><p class="poem-stanza">魂乎归来！恣志虑只。</p><p class="poem-stanza">孔雀盈园，畜鸾皇只！</p><p class="poem-stanza">鵾鸿群晨，杂鶖鸧只。</p><p class="poem-stanza">鸿鹄代游，曼骕驦只。</p><p class="poem-stanza">魂乎归来！凤凰翔只。</p><p class="poem-stanza">曼泽怡面，血气盛只。</p><p class="poem-stanza">永宜厥身，保寿命只。</p><p class="poem-stanza">室家盈廷，爵禄盛只。</p><p class="poem-stanza">魂乎归来！居室定只。</p><p class="poem-stanza">接径千里，出若云只。</p><p class="poem-stanza">三圭重侯，听类神只。</p><p class="poem-stanza">察笃夭隐，孤寡存只。</p><p class="poem-stanza">魂兮归来！正始昆只。</p><p class="poem-stanza">田邑千畛，人阜昌只。</p><p class="poem-stanza">美冒众流，德泽章只。</p><p class="poem-stanza">先威后文，善美明只。</p><p class="poem-stanza">魂乎归来！赏罚当只。</p><p class="poem-stanza">名声若日，照四海只。</p><p class="poem-stanza">德誉配天，万民理只。</p><p class="poem-stanza">北至幽陵，南交阯只。</p><p class="poem-stanza">西薄羊肠，东穷海只。</p><p class="poem-stanza">魂乎归来！尚贤士只。</p><p class="poem-stanza">发政献行，禁苛暴只。</p><p class="poem-stanza">举杰压陛，诛讥罢只。</p><p class="poem-stanza">直赢在位，近禹麾只。</p><p class="poem-stanza">豪杰执政，流泽施只。</p><p class="poem-stanza">魂乎来归！国家为只。</p><p class="poem-stanza">雄雄赫赫，天德明只。</p><p class="poem-stanza">三公穆穆，登降堂只。</p><p class="poem-stanza">诸侯毕极，立九卿只。</p><p class="poem-stanza">昭质既设，大侯张只。</p><p class="poem-stanza">执弓挟矢，揖辞让只。</p><p class="poem-stanza">魂乎来归！尚三王只。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
